from lib import *
S = SS('l27')
steps = [
    step("本机的一个裸仓库当远程,里面有 main、dev、feature/a、feature/b 四个分支,轻量标签 v1,注解标签 v2,还有自定义命名空间 refs/pull/1/head。git remote add 在 config 里写下的 fetch refspec 是 +refs/heads/*:refs/remotes/origin/*。第一次 git fetch 取回四个分支(origin/dev、origin/feature/a、origin/feature/b、origin/main)和两个标签;refs/pull/1/head 不在默认 refspec 的范围里,没有取回。", t=tl(S(1)), mark=lidx(S(1), '+refs/heads/*:refs/remotes/origin/*', 'refs/pull/1/head'), done=lidx(S(1), 'new branch', 'new tag', '没有 refs/pull/1/head'), kv=KV([['默认 refspec', '+refs/heads/*:refs/remotes/origin/*'], ['范围', '只匹配 refs/heads/ 下的分支'], ['refs/pull/…', '不取']], ['默认 refspec'])),
    step("语法 [+]<src>:<dst>:src 是远程的 ref,dst 是本地的 ref,* 通配符两边各出现一次。fetch 'refs/heads/feature/*:refs/remotes/o/f/*' 把 feature/a、feature/b 映射成 remotes/o/f/a、remotes/o/f/b;dst 里没有 * 的 'refs/heads/feature/*:refs/remotes/o/x' 被拒绝:fatal: invalid refspec;非分支的 ref 也能取:refs/pull/1/head:refs/mine/pr1 在本地创建了 refs/mine/pr1(任何命名空间都可以)。", t=tl(S(2)), mark=lidx(S(2), 'invalid refspec', 'refs/mine/pr1'), done=lidx(S(2), 'remotes/o/f/a', 'remotes/o/f/b'), kv=KV([['<src>:<dst>', '远程 ref 映射到本地 ref'], ['*', '两边都要有,各一个'], ['任意命名空间', 'refs/pull、refs/review 都可以取']], ['*'])),
    step("没有 + 前缀时,只允许快进:先 fetch main:refs/heads/copy 创建本地分支 copy(指向 m2);把 copy 重置到另一个不是 main 祖先的位置后,再取一次 main:refs/heads/copy,被拒绝 ! [rejected] main -> copy (non-fast-forward);加上 + 写成 +main:refs/heads/copy,输出 + <旧>...<新> main -> copy (forced update),强制覆盖。默认 refspec 开头的 + 就是为了让远程分支被强推之后,origin/* 仍能跟上。", t=tl(S(3)), mark=lidx(S(3), 'rejected', 'forced update'), done=lidx(S(3), 'copy <sha> m2'), kv=KV([['无 +', '只允许快进,否则 rejected'], ['有 +', '强制更新,输出 forced update'], ['默认 refspec', '开头有 +,所以 origin/* 总能跟上强推']], ['有 +'])),
    step("src 为空表示删除:先 push copy:refs/heads/tmp1 在远程创建 tmp1(ls-remote 看到),git push origin :refs/heads/tmp1 输出 - [deleted] tmp1,再 ls-remote 数出 0 行。dst 为空只取回、不指定本地 ref:git fetch origin dev 只写 FETCH_HEAD(* branch dev -> FETCH_HEAD),但同时顺手更新了 refs/remotes/origin/dev(* [new branch] dev -> origin/dev)——这是 fetch 的机会性更新,因为 origin 配有 fetch refspec 能映射 dev。", t=tl(S(4)), mark=lidx(S(4), '[deleted]', '-> FETCH_HEAD', 'dev        -> origin/dev'), done=lidx(S(4), 'refs/heads/tmp1', '机会性更新'), kv=KV([[':<dst> 推送', '空 src = 删除远程 ref'], ['fetch <ref>', '写 FETCH_HEAD'], ['机会性更新', '同时更新能映射到的 origin/*']], ['机会性更新'])),
    step("负 refspec(以 ^ 开头):给 origin 再加一条 ^refs/heads/feature/*,fetch 之后 refs/remotes/origin/ 下只有 HEAD、dev、main——feature/a、feature/b 被排除。再叠加 +refs/pull/*/head:refs/remotes/origin/pr/*,fetch 后多出 remotes/origin/pr/1。多条 fetch refspec 会叠加,一个 remote 可以同时取回多个命名空间。", t=tl(S(5)), mark=lidx(S(5), '^refs/heads/feature/*', 'remotes/origin/pr/1'), done=lidx(S(5), 'remotes/origin/HEAD remotes/origin/dev'), kv=KV([['^<pattern>', '排除匹配的 ref'], ['多条 refspec', '叠加,各取各的'], ['常见用法', '取 pull request 的 refs/pull/*/head']], ['^<pattern>'])),
    step("标签:只取 main(refspec 为 refs/heads/main:refs/remotes/origin/main)时,默认会自动跟随指向已取回提交的标签,本地得到 v1 和 v2;--no-tags 之后本地没有标签;--tags 取全部标签,得到 v1 v2;明确写 refs/tags/*:refs/tags/* 同样取回 v1 v2。自动跟随的条件是标签指向的对象已经被取回——本例里两个标签都指向 main 的提交。", t=tl(S(6)), mark=lidx(S(6), '--no-tags', '本地标签: (无)'), done=lidx(S(6), 'git fetch  ', '--tags', 'refs/tags/*:refs/tags/*'), kv=KV([['默认', '自动跟随指向已取回提交的标签'], ['--no-tags', '一个标签都不取'], ['--tags', '取全部标签']], ['默认'])),
    step("push 也是 refspec:git push origin HEAD:refs/heads/from-local 在远程创建 from-local 分支,HEAD:refs/review/42 在远程创建了一个任意命名空间的 ref(ls-remote 看到 refs/review/42)——Gerrit 的 refs/for/… 就是这种用法。push.default 未设置时默认 simple;当前分支 work 的上游是 origin/main,名字不一致,所以裸 git push origin 报错 fatal: The upstream branch of your current branch does not match the name of your current branch。", t=tl(S(7)), mark=lidx(S(7), 'refs/review/42', 'does not match'), done=lidx(S(7), 'refs/heads/from-local', 'push.default'), kv=KV([['HEAD:<ref>', '把当前提交推成远程的任意 ref'], ['push.default=simple', '分支名必须与上游相同'], ['refs/review/…', '自定义命名空间,服务器可用来做代码评审']], ['HEAD:<ref>'])),
]
A = mkarti('l27', 27, 'Git,refspec,fetch,push,远程跟踪,真实验证,动画演示',
    '用本机的裸仓库当远程,逐项验证 refspec:默认 +refs/heads/*:refs/remotes/origin/* 只匹配分支;<src>:<dst> 的 * 必须成对;无 + 只允许快进,有 + 强制更新;空 src 推送即删除;fetch <ref> 机会性更新 origin/*;^ 负 refspec 排除分支;标签的自动跟随与 --no-tags;push HEAD:refs/review/42 可推到任意命名空间。',
    'refspec 是 git fetch 和 git push 的核心语法:冒号两边是什么、加号是什么、星号怎么配对。这篇用一个本机的裸仓库当远程,逐个验证这些写法的行为,包括被拒绝的和强制覆盖的情形。',
    [('+', 'refspec 开头的加号:去掉它,非快进更新会被 rejected;有它则 forced update'), ('^', '负 refspec 排除匹配的 ref(本例排除 refs/heads/feature/*)'), ('HEAD:refs/review/42', '把当前提交推到远程的任意命名空间,不限于 refs/heads')],
    [('默认 refspec', '<p><code>git remote add</code> 写下 <code>+refs/heads/*:refs/remotes/origin/*</code>:把远程的所有分支映射成本地的 <code>origin/*</code>,开头的 <code>+</code> 允许强制更新(远程分支被强推后,<code>origin/*</code> 仍能跟上)。refs/pull/ 这样的非分支命名空间默认不取。</p>'),
     ('语法', '<p><code>[+]&lt;src&gt;:&lt;dst&gt;</code>。src 是远程的 ref,dst 是本地的 ref;通配符 <code>*</code> 在两边各出现一次,否则报 <code>invalid refspec</code>。目标可以是任意命名空间。</p>'),
     ('快进与强制', '<p>没有 <code>+</code> 时 fetch 到本地已有的 ref 只允许快进,否则 <code>! [rejected] … (non-fast-forward)</code>;加 <code>+</code> 则 <code>forced update</code>。</p>'),
     ('空的一边', '<p>push 时 src 为空(<code>:refs/heads/x</code>)表示删除远程的 ref;fetch 时省略 dst 只写 <code>FETCH_HEAD</code>,但 git 会顺手更新能被配置的 refspec 映射到的 <code>origin/*</code>。</p>'),
     ('负 refspec 与叠加', '<p><code>^</code> 开头的 refspec 排除匹配的 ref;多个 refspec 叠加,一个 remote 可以同时跟踪多个命名空间,比如 <code>+refs/pull/*/head:refs/remotes/origin/pr/*</code>。</p>'),
     ('标签', '<p>默认情况下,取回的提交上指向它的标签会被自动跟随;<code>--no-tags</code> 关闭,<code>--tags</code> 取全部。</p>'),
     ('push 的 refspec', '<p>push 同样是 refspec:<code>HEAD:refs/heads/新名字</code> 创建分支,<code>HEAD:refs/review/42</code> 创建任意命名空间的 ref;不带参数的 <code>git push</code> 受 <code>push.default</code> 约束,<code>simple</code> 要求分支名与上游相同。</p>')],
    steps,
    [ENV_I_GIT + '。远程是本机的一个裸仓库(file 路径),没有走网络;输出里的 hash、From 路径做了简化;第六节的“自动跟随”只验证了指向被取回提交的标签',
     '没有验证:fetch 的 --prune 与 refspec 的关系;push 的 --force-with-lease(见后面 push 一篇);remote.<name>.tagopt 配置;refspec 里的 glob 以外的模式;远程通过 ssh / http 时 refspec 的行为是否相同;push.default 的其它取值(matching、current、upstream)'],
    'refspec')
